import React, { useState, useEffect } from 'react';

interface MatrixInputProps {
    n: number;
    matrix: number[][];
    vector: number[];
    onChange: (matrix: number[][], vector: number[]) => void;
}

export const MatrixInput: React.FC<MatrixInputProps> = ({ n, matrix, vector, onChange }) => {
    // Локальный стейт для хранения того, что РЕАЛЬНО введено в инпуты (как строки)
    const [localMatrix, setLocalMatrix] = useState<string[][]>([]);
    const [localVector, setLocalVector] = useState<string[]>([]);

    // Синхронизируем локальный текст с приходящими данными (например, при загрузке файла)
    useEffect(() => {
        setLocalMatrix(matrix.map(row => row.map(val => val.toString())));
        setLocalVector(vector.map(val => val.toString()));
    }, [n]); // Обновляем только при изменении размерности

    const handleCellChange = (i: number, j: number, val: string) => {
        const cleanedVal = val.replace(',', '.');

        // Обновляем визуальное состояние (строку) сразу, чтобы точка не пропадала
        const newLocalMatrix = [...localMatrix];
        newLocalMatrix[i][j] = cleanedVal;
        setLocalMatrix(newLocalMatrix);

        // Отправляем наверх число, только если оно валидно
        if (cleanedVal !== '' && cleanedVal !== '-' && cleanedVal !== '.') {
            const num = parseFloat(cleanedVal);
            if (!isNaN(num)) {
                const newMatrix = matrix.map(row => [...row]);
                newMatrix[i][j] = num;
                onChange(newMatrix, vector);
            }
        }
    };

    const handleVecChange = (i: number, val: string) => {
        const cleanedVal = val.replace(',', '.');

        const newLocalVector = [...localVector];
        newLocalVector[i] = cleanedVal;
        setLocalVector(newLocalVector);

        if (cleanedVal !== '' && cleanedVal !== '-' && cleanedVal !== '.') {
            const num = parseFloat(cleanedVal);
            if (!isNaN(num)) {
                const newVector = [...vector];
                newVector[i] = num;
                onChange(matrix, newVector);
            }
        }
    };

    return (
        <div className="space-y-6 overflow-x-auto p-2">
            <div className="inline-block min-w-full align-middle">
                <div className="overflow-hidden border border-slate-200 rounded-lg shadow-sm">
                    <table className="min-w-full divide-y divide-slate-200">
                        <thead className="bg-slate-50">
                        <tr>
                            <th className="px-4 py-3 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest w-12">№</th>
                            {Array.from({ length: n }).map((_, j) => (
                                <th key={j} className="px-4 py-3 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                    A[{j + 1}]
                                </th>
                            ))}
                            <th className="px-4 py-3 text-center text-[10px] font-black text-slate-900 uppercase tracking-widest bg-slate-100">B</th>
                        </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-slate-200">
                        {Array.from({ length: n }).map((_, i) => (
                            <tr key={i} className="hover:bg-slate-50 transition-colors">
                                <td className="px-4 py-2 text-sm font-bold text-slate-300 border-r">{i + 1}</td>
                                {Array.from({ length: n }).map((_, j) => (
                                    <td key={j} className="px-2 py-2">
                                        <input
                                            type="text"
                                            value={localMatrix[i]?.[j] ?? ''}
                                            onChange={(e) => handleCellChange(i, j, e.target.value)}
                                            className="w-full px-2 py-1.5 text-center font-mono text-sm border border-slate-200 rounded focus:ring-2 focus:ring-slate-900 focus:outline-none transition-all"
                                            placeholder="0"
                                        />
                                    </td>
                                ))}
                                <td className="px-2 py-2 bg-slate-50">
                                    <input
                                        type="text"
                                        value={localVector[i] ?? ''}
                                        onChange={(e) => handleVecChange(i, e.target.value)}
                                        className="w-full px-2 py-1.5 text-center font-mono text-sm border border-slate-300 rounded bg-white focus:ring-2 focus:ring-slate-900 focus:outline-none transition-all font-bold"
                                        placeholder="0"
                                    />
                                </td>
                            </tr>
                        ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="flex gap-4 text-[10px] font-bold uppercase text-slate-400 tracking-tighter">
                <div className="flex items-center gap-1.5">
                    <div className="w-2 h-2 rounded-full bg-slate-200"></div>
                    <span>Используйте точку (.) для дробей</span>
                </div>
                <div className="flex items-center gap-1.5">
                    <div className="w-2 h-2 rounded-full bg-slate-900"></div>
                    <span>B — вектор правой части</span>
                </div>
            </div>
        </div>
    );
};
